"use strict";(self.webpackChunkpa_openapi_docs=self.webpackChunkpa_openapi_docs||[]).push([[9434],{6218:e=>{e.exports=JSON.parse('{"blogPosts":[{"id":"2026-05-27-update","metadata":{"permalink":"/developers/en/blog/2026-05-27-update","source":"@site/i18n/en/docusaurus-plugin-content-blog/2026-05-27-update/index.md","title":"Introduction to Open API Changes in May 2026","description":"Hello,","date":"2026-05-27T00:00:00.000Z","formattedDate":"May 27, 2026","tags":[{"label":"patch","permalink":"/developers/en/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2026-05-27-update","title":"Introduction to Open API Changes in May 2026","tags":["patch"]},"nextItem":{"title":"Platform Update Notice \u2013 April 2025 (effective date of April 24)","permalink":"/developers/en/blog/2025-04-24-update"}},"content":"Hello,\\r\\nThis is the Naver Performance Display Ads Open API team.\\r\\nWe would like to inform you of the changes to the Naver Performance Display Ads platform in May 2026. Please refer to the details below.\\r\\n\\r\\n**\u25a0 Summary of Changes**\\r\\n\\r\\n[1] New Ad Creative Creation APIs\\r\\n\\r\\n[2] New Ad Creative Asset (Image/Video) Upload APIs\\r\\n\\r\\n**\u25a0 Details**\\r\\n\\r\\n**[1] New Ad Creative Creation APIs**\\r\\n\\r\\nAd creative creation, which was previously available only through the Naver Performance Display Ads site, is now extended to be performed directly via Open APIs. Depending on the ad group\'s creative type (creativeType) and creative template (creativeTemplateCode), the following creative types are supported:\\r\\n\\r\\n- Image Banner Creative Creation API (Smart Channel / Mobile DA)\\r\\n- Native Image Creative Creation API (Feed / Banner)\\r\\n  - Supported templates: NATIVE_SINGLE_IMAGE_V2, NATIVE_SINGLE_IMAGE_PC, FEED_SINGLE_IMAGE, FEED_SINGLE_IMAGE_SQUARE, FEED_SINGLE_IMAGE_2TO3, NATIVE_SINGLE_IMAGE_COMMUNICATION\\r\\n- Collection Creative Creation API (Image Collection / Video Collection)\\r\\n- Video Creative Creation API (Feed / Banner / In-stream)\\r\\n  - Supported templates: NATIVE_SINGLE_VIDEO, FEED_SHORTFORM_VIDEO, FEED_SINGLE_VIDEO, INSTREAM_VIDEO\\r\\n\\r\\n> To create Native Image, Collection, or Video creatives, a profile must be registered in advance under Ad Account Management > Profile Management. For required and optional parameters per template, please refer to the Ad Creative Guide documentation.\\r\\n\\r\\n**[2] New Ad Creative Asset (Image/Video) Upload APIs**\\r\\n\\r\\nDedicated APIs are now provided to pre-upload image and video files for ad creative creation. The ID value returned in the upload response can be used directly as the imageNo, videoNo, or thumbnailImageNo parameter in the creative creation APIs.\\r\\n\\r\\n- Image Upload API\\r\\n- Video Upload API\\r\\n  - Only one concurrent call is allowed per ad account.\\r\\n  - Video files up to 100MB can be uploaded; for larger files, please upload directly via the Naver Performance Display Ads site.\\r\\n  - callbackUrl registration is supported to receive notifications upon upload/encoding completion or failure.\\r\\n\\r\\n**Effective Date**\\r\\n\\r\\nWednesday, May 27, 2026\\r\\n\\r\\n**Changes**\\r\\n\\r\\n- Added Ad Creative Creation APIs\\r\\n  - New APIs for Image Banner / Native Image / Collection / Video (Feed, Banner, In-stream) creatives\\r\\n  - Added new Native Image template: NATIVE_SINGLE_IMAGE_COMMUNICATION\\r\\n- Added Ad Creative Asset Upload APIs\\r\\n  - New Image Upload API and Video Upload API (with callback support)\\r\\n\\r\\nIf you have any other questions, please contact us via the Naver Performance Display Ads API inquiry channel.\\r\\n\\r\\nThank you."},{"id":"2025-04-24-update","metadata":{"permalink":"/developers/en/blog/2025-04-24-update","source":"@site/i18n/en/docusaurus-plugin-content-blog/2025-04-24-update/index.md","title":"Platform Update Notice \u2013 April 2025 (effective date of April 24)","description":"Dear users,","date":"2025-04-24T00:00:00.000Z","formattedDate":"April 24, 2025","tags":[{"label":"patch","permalink":"/developers/en/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2025-04-24-update","title":"Platform Update Notice \u2013 April 2025 (effective date of April 24)","tags":["patch"]},"prevItem":{"title":"Introduction to Open API Changes in May 2026","permalink":"/developers/en/blog/2026-05-27-update"},"nextItem":{"title":"Platform Update Notice \u2013 March 2025 (effective date of March 14)","permalink":"/developers/en/blog/2025-03-14-update"}},"content":"Dear users,\\r\\nWe would like to announce a new update to the NAVER Performance DA platform in April 2025.\\r\\n\\r\\nThis update includes the following:\\r\\n\\r\\n**\u25a0 Changes**\\r\\n\\r\\n[1] Removal of the \'convPartner\' field in the Performance API responses\\r\\n\\r\\n**\u25a0 Details**\\r\\n\\r\\n[1] Removal of the \'convPartner\' field in the Performance API responses\\r\\n\\r\\nIt was previously provided as one of the response fields in both the Past Conversion Data and Real-Time Conversion Data reports. However, due to difficulties in maintaining clear contextual distinction, it will no longer be provided.\\r\\n\\r\\n**Effective Date**\\r\\n\\r\\nThursday, April 24, 2025\\r\\n\\r\\n**Changes Made**\\r\\n\\r\\n- Removal of the \'convPartner\' field from the responses of Get past conversion data\\r\\n- Removal of the \'convPartner\' field from the responses of Get real-time conversion data\\r\\n\\r\\nIf you have any questions, feel free to contact us at\xa0agency_cs@navercorp.com\\r\\n\\r\\nThank you!\\r\\n\\r\\nBest regards, The NAVER Performance DA Open API Team"},{"id":"2025-03-14-update","metadata":{"permalink":"/developers/en/blog/2025-03-14-update","source":"@site/i18n/en/docusaurus-plugin-content-blog/2025-03-14-update/index.md","title":"Platform Update Notice \u2013 March 2025 (effective date of March 14)","description":"Dear users,","date":"2025-03-14T00:00:00.000Z","formattedDate":"March 14, 2025","tags":[{"label":"patch","permalink":"/developers/en/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2025-03-14-update","title":"Platform Update Notice \u2013 March 2025 (effective date of March 14)","tags":["patch"]},"prevItem":{"title":"Platform Update Notice \u2013 April 2025 (effective date of April 24)","permalink":"/developers/en/blog/2025-04-24-update"},"nextItem":{"title":"Platform Update Notice \u2013 September 2024 (effective date of September 26)","permalink":"/developers/en/blog/2024-09-26-update"}},"content":"Dear users,\\r\\n\\r\\nWe are excited to announce a new update to the NAVER Performance DA platform in March 2025.\\r\\nThis update includes the following:\\r\\n\\r\\n**\u25a0 Changes**\\r\\n\\r\\n[1] Ad placement reorganization\\r\\n\\r\\n**\u25a0 Details**\\r\\n\\r\\n[1] Ad placement reorganization\\r\\n\\r\\nTo optimize ad placements automatically, the ad placements within \u201cNaver\u201d and \u201cNaver Family Media\u201d will be integrated into a unified placement category called \u201cNaver+\u201d.\\r\\n\\r\\n**Effective Date**\\r\\n\\r\\nFriday, March 14, 2025\\r\\n\\r\\n**Changes Made**\\r\\n\\r\\nThe ad placements within \u201cNAVER\u201d and \u201cNAVER Family Media\u201d will be integrated into a unified category called \u201cNAVER+\u201d for automatic optimization.\\r\\nAs a result, the \u201cNAVER Family Media\u201d placement codes (placementGroupCodes) will no longer be available when creating or modifying ad groups.\\r\\n\\r\\n| Value | Description |\\r\\n|--|--|\\r\\n| BAND | (Deprecated) NAVER\'s family service > Feed area | \\r\\n| F_BANNER | (Deprecated) NAVER\'s family service > Banner area | \\r\\n| F_SMARTCHANNEL | (Deprecated) NAVER\'s family service > Smart Channel | \\r\\n\\r\\n- API > Types > PlacementGroup\\r\\n- Ad API > Ad groups > List of ad groups > placementGroupCodes\\r\\n- Ad API > Ad groups > Create an ad group\xa0> placementGroupCodes\\r\\n- Ad API > Ad groups > Update device/placement > placementGroupCodes\\r\\n\xa0\\r\\nIf you have any questions, feel free to contact us at\xa0agency_cs@navercorp.com\\r\\n\\r\\nThank you!\\r\\n\\r\\nBest regards, The NAVER Performance DA Open API Team"},{"id":"2024-09-26-update","metadata":{"permalink":"/developers/en/blog/2024-09-26-update","source":"@site/i18n/en/docusaurus-plugin-content-blog/2024-09-26-update/index.md","title":"Platform Update Notice \u2013 September 2024 (effective date of September 26)","description":"Dear users,","date":"2024-09-26T00:00:00.000Z","formattedDate":"September 26, 2024","tags":[],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2024-09-26-update","title":"Platform Update Notice \u2013 September 2024 (effective date of September 26)","tags":[]},"prevItem":{"title":"Platform Update Notice \u2013 March 2025 (effective date of March 14)","permalink":"/developers/en/blog/2025-03-14-update"},"nextItem":{"title":"Welcome!","permalink":"/developers/en/blog/welcome"}},"content":"Dear users,\\r\\n\\r\\nWe are excited to announce a new update to the NAVER Performance DA platform in September 2024.\\r\\n\\r\\nThis update includes the following:\\r\\n\\r\\n\u25a0 Changes\\r\\n\\r\\n[1] How the Open API integrates\\r\\n\\r\\n\u25a0 Details\\r\\n\\r\\n[1] Location\\r\\n\\r\\nAPI > Ad API > Creatives > Changes to parameters/responses within the List of Creatives API\\r\\n\\r\\n- Effective Date\\r\\n\\r\\n  Thursday, September 26, 2024\\r\\n\\r\\n- Changes Made\\r\\n  - The \u2018campaignNo\u2019 field is deleted upon retrieval of the List of Creatives API\\r\\n  - The \'adSetName\u2019, \u2018campaignName\u2019, and \u2018campaignNo\' are deleted within the response of the List of Creatives API\\r\\n\\r\\nIf you have any questions, feel free to contact us at agency_cs@navercorp.com\\r\\n\\r\\nThank you!\\r\\n\\r\\nBest regards,\\r\\nThe NAVER Performance DA Open API Team"},{"id":"welcome","metadata":{"permalink":"/developers/en/blog/welcome","source":"@site/i18n/en/docusaurus-plugin-content-blog/2023-02-03-welcome/index.md","title":"Welcome!","description":"Welcome to our notice board.","date":"2023-02-03T00:00:00.000Z","formattedDate":"February 3, 2023","tags":[{"label":"hello","permalink":"/developers/en/blog/tags/hello"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"welcome","title":"Welcome!","tags":["hello"]},"prevItem":{"title":"Platform Update Notice \u2013 September 2024 (effective date of September 26)","permalink":"/developers/en/blog/2024-09-26-update"}},"content":"Welcome to our notice board.\\r\\n\\r\\nHere, you will find details about all updates, announcements, and important information related to our APIs.\\r\\n\\r\\n![Docusaurus Plushie](./docusaurus-plushie-banner.jpeg)"}]}')}}]);